let w=12+24+8+(d.i?34:0)+vw+(d.n?10+nw:0)+(d.gain||d.cost?12+38:0)+(d.seg?12+d.seg[1]*11:0)+(d.loud?12+20:0)+12;
const x0=Math.round(VW/2-w/2),y0=yy||VH-96,h=36;plate(x0,y0,w,h);g.strokeStyle=col;g.globalAlpha=.55;g.lineWidth=1;g.strokeRect(x0+.5,y0+.5,w-1,h-1);g.globalAlpha=1;
let x=x0+12;g.fillStyle='#2a313b';g.fillRect(x,y0+8,24,20);g.strokeStyle='#9aa6b2';g.strokeRect(x+.5,y0+8.5,23,19);g.fillStyle='#e8edf2';g.font='bold 13px monospace';g.textAlign='center';g.fillText(key,x+12,y0+23);x+=32;
