/* Sichtkegel einer Wache: Strahlen von der Wache, die an blickdichten Kacheln (Waende, Saeulen) enden, damit der Kegel nicht durch Waende scheint */
function coneRays(x,y,a,fov,rng){const n=40,pts=[[x,y]];for(let i=0;i<=n;i++){const an=a-fov+2*fov*i/n,cx=Math.cos(an),cy=Math.sin(an);let r=0;while(r<rng){r+=4;if(isOpq(Math.floor((x+cx*r)/T),Math.floor((y+cy*r)/T)))break}r=Math.min(r,rng);pts.push([x+cx*r,y+cy*r])}return pts}
function cone(x,y,a,fov,rng,col,al){const pts=coneRays(x,y,a,fov,rng);
const q=g.createRadialGradient(x,y,0,x,y,rng);q.addColorStop(0,'rgba('+col+','+al+')');q.addColorStop(1,'rgba('+col+',0)');g.fillStyle=q;g.beginPath();g.moveTo(pts[0][0],pts[0][1]);for(let i=1;i<pts.length;i++)g.lineTo(pts[i][0],pts[i][1]);g.closePath();g.fill()}
function wedge(x,y,a,fov,rng,col,al){const q=g.createRadialGradient(x,y,0,x,y,rng);q.addColorStop(0,'rgba('+col+','+al+')');q.addColorStop(1,'rgba('+col+',0)');g.fillStyle=q;g.beginPath();g.moveTo(x,y);g.arc(x,y,rng,a-fov,a+fov);g.closePath();g.fill()}
